pragma solidity >=0.8.0;
contract EventOrderPackM4 {
    event Mark(uint8 indexed tag, string indexed s, bytes b, address indexed who);
    uint8 public flag;
    string public s1;
    bytes public b1;
    address public last;
    function mix() external {
        flag = 1;
        s1 = "a";
        b1 = hex"00";
        last = msg.sender;
        emit Mark(1, s1, b1, msg.sender);
        emit Mark(2, s1, b1, msg.sender);
    }
    function getAll() external view returns (uint8, string memory, bytes memory, address) {
        return (flag, s1, b1, last);
    }
}
